import bvsolver
import sys


# 2025 qiangwangbei quals crypto ezran
# attachment:
"""
from Crypto.Util.number import *
from random import *

f = open('flag.txt', 'r')
flag = f.read().encode()

gift=b''
for i in range(3108):
    r1 = getrandbits(8)
    r2 = getrandbits(16)
    x=(pow(r1, 2*i, 257) & 0xff) ^ r2
    c=long_to_bytes(x, 2)
    gift+=c

m = list(flag)
for i in range(2025):
    shuffle(m)

c = "".join(list(map(chr,m)))

f = open('output.txt', 'w')
f.write(f"gift = {bytes_to_long(gift)}\n")
f.write(f"c = {c}\n")
"""

# learned from https://dexterjie.github.io/2025/10/20/2025%E5%BC%BA%E7%BD%91%E6%9D%AF/#ezran

sys.set_int_max_str_digits(20000)
# from given output.txt
gift = int(
    ""
)
c = ")9Lsu_4s_eb__otEli_nhe_tes5gii5sT@omamkn__ari{efm0__rmu_nt(0Eu3_En_og5rfoh}nkeoToy_bthguuEh7___u"

# create equations
solver = bvsolver.Solver([32] * 624)
state = solver.bitvectors()

rng = bvsolver.CPythonRandom(
    state,
    # newly created Random instance has its index equal to 624
    624,
)
# newly created Random instance has its first element equal to 0x80000000
# see init_by_array in _randommodule.c
zeros = [state[0] ^ 0x80000000]
data = int.to_bytes(gift, (gift.bit_length() + 7) // 8)
assert len(data) == 3108 * 2
for i in range(3108):
    # the higher 8 bits of x equals the higher 8 bits of r2
    x = int.from_bytes(data[i * 2 : i * 2 + 2])
    rng.getrandbits(8)
    zeros.append((rng.getrandbits(16) >> 8) ^ (x >> 8))

# find solutions
for sol in solver.solve(zeros):
    state_recover = [s.get(sol) for s in state]

    # recreate random number generator
    rng_recover = bvsolver.CPythonRandom(state_recover, 624).to_cpython_random()
    good = True
    for i in range(3108):
        r1 = rng_recover.getrandbits(8)
        r2 = rng_recover.getrandbits(16)
        x = (pow(r1, 2 * i, 257) & 0xFF) ^ r2
        if x == int.from_bytes(data[i * 2 : i * 2 + 1]):
            good = False
            break

    if not good:
        continue

    # find shuffle mapping
    m = [i for i in range(len(c))]
    for i in range(2025):
        rng_recover.shuffle(m)

    # reverse mapping
    flag = ""
    for i in range(len(c)):
        flag += c[m.index(i)]

    if "flag{" in flag:
        print(flag)
